package app.boardlens.companion;
import android.app.Application;import android.graphics.*;import android.view.*;import android.widget.*;import org.junit.Test;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import java.io.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35,application=Application.class) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class MobileDashboardTest {
 private int starts,stops;
 private PhoneDashboard dashboard(){return new PhoneDashboard(RuntimeEnvironment.getApplication(),new PhoneDashboard.Actions(){public void start(){starts++;}public void stop(){stops++;}public void hide(){}public void scan(){}public void settings(){}public void help(){}public void back(){}public boolean option(String k,boolean f){return f;}public void option(String k,boolean v,boolean unused){}});}
 private Button button(View v,String text){if(v instanceof Button&&((Button)v).getText().toString().equals(text))return (Button)v;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++){Button found=button(g.getChildAt(i),text);if(found!=null)return found;}}return null;}
 @Test public void controlsFollowTheSessionState(){PhoneDashboard s=dashboard();s.render(false,"Ready","Open a board","Evaluation",.5f,null);button(s.root,"Start screen analysis").performClick();assertEquals(1,starts);assertFalse(button(s.root,"Stop").isEnabled());s.render(true,"Reading","Knight to f3","Stockfish +0.31",.55f,null);assertFalse(button(s.root,"Analysis is running").isEnabled());button(s.root,"Stop").performClick();assertEquals(1,stops);}
 @Test public void narrowDashboardAndSelectorFit()throws Exception{PhoneDashboard s=dashboard();s.engine.setText("Maia 3 · 5M · on this phone");s.render(true,"White at bottom · White to move","1. Knight to f3\nReply: Knight to f6","Stockfish · +0.31 · White’s perspective",.55f,null);s.root.measure(View.MeasureSpec.makeMeasureSpec(360,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(800,View.MeasureSpec.EXACTLY));s.root.layout(0,0,360,800);assertTrue(s.root.getChildAt(0).getWidth()<=360);File folder=new File("build/reports/mobile-previews");folder.mkdirs();Bitmap image=Bitmap.createBitmap(360,800,Bitmap.Config.ARGB_8888);s.root.draw(new Canvas(image));try(FileOutputStream out=new FileOutputStream(new File(folder,"phone-dashboard.png"))){image.compress(Bitmap.CompressFormat.PNG,100,out);}View row=new MobileUi(RuntimeEnvironment.getApplication()).choice("Move engine",new String[]{"Electric Shockwave Gambit · original Tiny bot"},0,i->{});row.measure(View.MeasureSpec.makeMeasureSpec(360,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(100,View.MeasureSpec.AT_MOST));assertTrue(row.getMeasuredHeight()<=100);}
 @Test public void appScreenTransitionsKeepOurPreviewExcluded(){Object phone=new Object(),models=new Object();PhoneUiVisibility.start(phone);assertTrue(ScreenService.phoneVisible);PhoneUiVisibility.start(models);PhoneUiVisibility.stop(phone);assertTrue(ScreenService.phoneVisible);PhoneUiVisibility.stop(models);assertFalse(ScreenService.phoneVisible);}
}
